insert into "CozyCookBookSchema".folders (id, name, blurb, user_id, is_public, position) values
  ('8f249819-e296-594e-b059-96112a258579', 'Vegetarian', 'Eggs and dairy welcome. Paneer, halloumi and legumes carry the protein.', null, true, 5120)
on conflict (id) do update set name = excluded.name, blurb = excluded.blurb;

insert into "CozyCookBookSchema".recipes
  (id, title, ingredients, steps, folder_id, user_id, meal, is_public, position)
select r.id, r.title,
  (select coalesce(jsonb_agg(jsonb_build_object('id', gen_random_uuid(), 'name', n, 'isChecked', false) order by o), '[]'::jsonb)
   from unnest(r.ing) with ordinality as t(n, o)),
  (select coalesce(jsonb_agg(jsonb_build_object('id', gen_random_uuid(), 'text', st, 'isChecked', false) order by o), '[]'::jsonb)
   from unnest(r.steps) with ordinality as t(st, o)),
  '8f249819-e296-594e-b059-96112a258579', null, r.meal, true, r.pos
from (values
  ('2e13e4bf-ec7e-5b21-aa1d-57f1d86f190a'::uuid, 'Shakshuka', array['6 large eggs','1 can crushed tomatoes','2 red bell peppers, sliced','1 yellow onion, sliced','4 cloves garlic, sliced','1 tsp ground cumin','1 tsp sweet paprika','3 tbsp olive oil','1/2 cup feta cheese','1/4 cup fresh cilantro'], array['Soften the peppers and onion slowly, a full 15 minutes.','Add garlic and spices, then the tomatoes, and simmer until thick.','Make wells and crack in the eggs; cover and cook until the whites just set.','Feta and cilantro over the top, bread alongside.'], 'Breakfast', 0),
  ('57ae974e-0c82-5e53-8813-1eb3e952f136'::uuid, 'Greek Yogurt Protein Bowl', array['2 cups Greek yogurt','1/4 cup honey','1/2 cup granola','1 cup strawberries','1/4 cup walnuts','2 tbsp chia seeds','1 scoop whey protein powder'], array['Whisk the protein powder into the yogurt until no streaks remain.','Layer with granola, berries, walnuts and chia.','Honey last. Around 40 g of protein.'], 'Breakfast', 1024),
  ('be20fb87-42d5-534e-9be4-6beb90e27ad7'::uuid, 'Masala Omelette', array['4 large eggs','1 yellow onion, minced','2 green chilies, minced','1 tomato, diced','1/4 cup fresh cilantro','1/2 tsp ground turmeric','2 tbsp ghee','Black pepper to taste'], array['Beat the eggs hard until frothy.','Fold in the onion, chilies, tomato, cilantro and turmeric.','Cook in ghee on medium, pulling the edges in.','Fold when the top is still slightly wet.'], 'Breakfast', 2048),
  ('44084db1-632e-530d-98e8-4501c574a0d3'::uuid, 'Ricotta Pancakes', array['1 cup ricotta','1 cup all-purpose flour','3 large eggs, separated','3/4 cup whole milk','2 tbsp granulated sugar','1 tsp baking powder','1 lemon, zested','2 tbsp butter','1 cup blueberries'], array['Whisk the yolks, ricotta, milk and zest together.','Fold in the flour, sugar and baking powder.','Whip the whites to soft peaks and fold them in last — this is what makes them light.','Cook gently in butter; they colour faster than ordinary pancakes.'], 'Breakfast', 3072),
  ('f0715008-6c8b-5a69-8bc9-95a5eeb110bc'::uuid, 'Halloumi and Quinoa Salad', array['250g halloumi, sliced','1 cup quinoa','1 cucumber, diced','1 cup cherry tomatoes, halved','1/2 red onion, sliced thin','1/4 cup fresh mint','3 tbsp olive oil','2 tbsp lemon juice','1/4 cup pistachios'], array['Cook the quinoa and spread it out to cool so it does not steam itself soggy.','Dry-fry the halloumi in a hot pan until deeply golden on both sides.','Toss the quinoa with vegetables, herbs, oil and lemon.','Halloumi on top while still squeaky. Roughly 28 g of protein.'], 'Lunch', 4096),
  ('76209c3f-1da4-5a9b-8648-765542986d96'::uuid, 'Paneer Tikka Wrap', array['400g paneer, cubed','1 cup yogurt','2 tbsp ginger garlic paste','2 tsp garam masala','1 red bell pepper, chunked','1 red onion, chunked','4 rotis','1/2 cup mint chutney','1 lemon'], array['Marinate the paneer and vegetables in spiced yogurt for an hour. No longer, or the paneer toughens.','Thread onto skewers and grill until charred at the edges.','Warm the rotis, spread with chutney, fill and squeeze lemon over. About 30 g of protein.'], 'Lunch', 5120),
  ('beba629a-fffd-5dec-8fea-9bd9418c156f'::uuid, 'Caprese Sandwich', array['1 ciabatta loaf','250g fresh mozzarella, sliced','2 heirloom tomatoes, sliced','1/4 cup fresh basil','3 tbsp olive oil','2 tbsp balsamic vinegar','Salt to taste','Black pepper to taste'], array['Salt the tomato slices and drain them 10 minutes.','Split and lightly toast the ciabatta.','Layer mozzarella, tomato and basil; oil, vinegar, salt and a lot of pepper.','Press under a weight for 10 minutes.'], 'Lunch', 6144),
  ('cd1b2fad-f37b-5b04-8aa9-4af0323c3ff4'::uuid, 'Egg Salad Sandwich', array['6 hard-boiled eggs','3 tbsp mayonnaise','1 tbsp Dijon mustard','2 stalks celery, minced','2 tbsp fresh chives','8 slices bread','Salt to taste','Black pepper to taste'], array['Chop the eggs coarsely — whites and yolks should stay distinguishable.','Fold in the mayonnaise, mustard, celery and chives.','Season well and chill an hour before making the sandwiches.'], 'Lunch', 7168),
  ('0025141f-3992-50e7-8269-ef184153ecaf'::uuid, 'Spinach and Feta Quiche', array['1 pie crust','6 large eggs','1 cup heavy cream','4 cups spinach','1 cup feta cheese','1 yellow onion, sliced','2 tbsp butter','Pinch of nutmeg','Black pepper to taste'], array['Blind-bake the crust 15 minutes at 400°F.','Cook the spinach down and squeeze out every drop of water.','Soften the onion in butter.','Whisk eggs, cream and nutmeg; combine with the fillings.','Bake at 350°F for 40 minutes until the centre barely trembles.'], 'Lunch', 8192),
  ('f922a7a6-aba2-5fad-8597-7fa076478c6d'::uuid, 'Eggplant Parmesan', array['3 eggplants, sliced','2 cups breadcrumbs','3 large eggs, beaten','1 cup all-purpose flour','1 can crushed tomatoes','500g fresh mozzarella','1 1/2 cups Parmesan, grated','1/4 cup fresh basil','Oil for frying'], array['Salt the eggplant and drain an hour, then pat dry.','Flour, egg, breadcrumb, and fry until golden.','Layer with sauce and both cheeses.','Bake at 375°F for 40 minutes and rest before cutting.'], 'Dinner', 9216),
  ('2462d02f-7544-5daf-aed0-fa8ddeb75a22'::uuid, 'Paneer Butter Masala', array['500g paneer, cubed','1 can crushed tomatoes','1/2 cup cashews','1 yellow onion, chunked','1 tbsp ginger garlic paste','1 tsp garam masala','1 tsp kashmiri chili powder','1/2 cup heavy cream','5 tbsp butter','1 tbsp kasuri methi'], array['Simmer the tomatoes, cashews, onion and ginger garlic paste 20 minutes, then blend and sieve.','Return to the pan with butter and spices and cook 10 minutes.','Add cream and paneer and warm through gently — boiling makes paneer rubbery.','Kasuri methi crushed over the top. Around 26 g of protein.'], 'Dinner', 10240),
  ('49496a75-0c19-55d1-b177-b72c06b784d0'::uuid, 'Mushroom Risotto', array['1 1/2 cups arborio rice','1 lb cremini mushrooms, sliced','1 yellow onion, minced','1/2 cup white wine','6 cups vegetable stock','4 tbsp butter','1 cup Parmesan, grated','2 fresh thyme sprigs'], array['Brown the mushrooms in batches and set aside.','Soften the onion, toast the rice, deglaze with wine.','Add hot stock a ladle at a time for 18 minutes.','Fold the mushrooms back in and beat in cold butter and parmesan off the heat.'], 'Dinner', 11264),
  ('02d5d3d5-31dc-5edd-b0db-2796f0491893'::uuid, 'Black Bean and Sweet Potato Enchiladas', array['2 sweet potatoes, cubed','2 cans black beans','8 tortillas','2 cups enchilada sauce','2 cups shredded cheese','1 yellow onion, diced','1 tsp ground cumin','1 tbsp olive oil','1 avocado, sliced'], array['Roast the sweet potato with cumin until the edges caramelise.','Mix with the beans and softened onion.','Fill and roll the tortillas, seam-side down in a dish.','Cover with sauce and cheese and bake at 375°F for 25 minutes.'], 'Dinner', 12288),
  ('a1448034-faf9-50ad-ae2a-7e2a46f26be8'::uuid, 'Palak Paneer', array['500g paneer, cubed','2 lbs spinach','1 yellow onion, minced','2 green chilies','1 tbsp ginger garlic paste','1 tsp ground cumin','1/2 tsp garam masala','3 tbsp ghee','1/4 cup heavy cream'], array['Blanch the spinach 90 seconds and shock it in ice water to keep it green.','Blend coarsely with the chilies.','Brown the onion, add ginger garlic paste and spices.','Add the puree and cook only five minutes.','Fold in paneer and cream. Around 24 g of protein.'], 'Dinner', 13312),
  ('c814859f-f2f6-5717-8112-e755082f040f'::uuid, 'Stuffed Bell Peppers', array['4 red bell peppers, halved','1 cup quinoa','1 can black beans','1 cup corn','1 yellow onion, diced','1 tsp ground cumin','1 1/2 cups shredded cheese','1 can diced tomatoes','1/4 cup fresh cilantro'], array['Par-roast the pepper halves 15 minutes so they are not raw in the middle.','Cook the quinoa and mix with beans, corn, onion, tomato and cumin.','Fill the peppers, top with cheese, and bake 25 minutes at 375°F.'], 'Dinner', 14336),
  ('6c8ac94f-b9e2-5ac3-abb5-1e8b1f73b59b'::uuid, 'Vegetable Lasagne', array['1 lb lasagne sheets','2 zucchini, sliced','2 eggplants, sliced','500g ricotta','1 can crushed tomatoes','500g fresh mozzarella','1 cup Parmesan, grated','3 tbsp olive oil','1/4 cup fresh basil'], array['Roast the zucchini and eggplant first to drive off water.','Simmer the tomatoes with basil for 20 minutes.','Layer sauce, pasta, ricotta, vegetables and mozzarella twice over.','Bake covered 30 minutes, uncovered 15 more, and rest 20 minutes.'], 'Dinner', 15360),
  ('a1b2df12-5eda-569f-9b83-55a26fc9ccd4'::uuid, 'Chickpea Shawarma Bowl', array['2 cans chickpeas','2 tsp ground cumin','2 tsp sweet paprika','1 tsp ground turmeric','3 tbsp olive oil','1 cup Greek yogurt','2 tbsp tahini','1 cucumber, diced','1 cup cherry tomatoes','2 cups cooked rice','1 lemon'], array['Toss the chickpeas in oil and spices and roast at 425°F for 30 minutes until crisp.','Whisk the yogurt, tahini and lemon into a sauce.','Build over rice with the salad vegetables.','About 25 g of protein a bowl.'], 'Dinner', 16384),
  ('4df72857-deb2-5767-96ef-121f15e69b31'::uuid, 'Caprese Skewers', array['250g mozzarella pearls','2 cups cherry tomatoes','1/4 cup fresh basil','3 tbsp olive oil','2 tbsp balsamic glaze','Black pepper to taste'], array['Thread tomato, basil and mozzarella onto short skewers.','Oil and glaze just before serving.','Pepper over the top.'], 'Snack', 17408),
  ('a9c9778a-e642-5151-bce6-f279086e7b60'::uuid, 'Spinach Artichoke Dip', array['2 cups spinach','1 can artichoke hearts, chopped','8 oz cream cheese','1/2 cup sour cream','1 cup Parmesan, grated','1 cup shredded cheese','2 cloves garlic, minced'], array['Squeeze the spinach and artichokes dry.','Beat the cream cheese and sour cream smooth with the garlic.','Fold everything together and bake at 375°F for 25 minutes until bubbling and browned on top.'], 'Snack', 18432),
  ('f4eb981c-d900-54b0-a163-175d85ce80e6'::uuid, 'Paneer Pakora', array['400g paneer, sliced','1 cup chickpea flour','1 tsp kashmiri chili powder','1/2 tsp ground turmeric','1/4 tsp asafoetida','1/2 tsp ground cumin','Oil for frying','Salt to taste'], array['Whisk a batter thick enough to coat the back of a spoon.','Rest it 15 minutes.','Dip the paneer and fry at 350°F until pale gold — too dark and the paneer squeaks.','Drain on a rack and salt immediately.'], 'Snack', 19456),
  ('28a567fb-5800-58df-9603-1be84b781016'::uuid, 'Cheese Quesadilla', array['4 tortillas','2 cups shredded cheese','1 jalapeño, sliced','1/4 cup fresh cilantro','2 tbsp butter','1/2 cup sour cream'], array['Butter the outside of the tortilla, not the pan.','Cheese, jalapeño and cilantro on one half; fold.','Cook on medium-low so the cheese melts before the outside burns.','Rest a minute before cutting or it all runs out.'], 'Snack', 20480),
  ('67a05e5c-7529-5145-b103-55d8d91b94ec'::uuid, 'Cheesecake Brownies', array['1 cup butter','1 1/2 cups granulated sugar','4 large eggs','1 cup cocoa powder','1 cup all-purpose flour','8 oz cream cheese','1/4 cup granulated sugar','1 large egg','1 tsp vanilla extract'], array['Make the brownie batter and reserve a quarter of it.','Beat the cream cheese with sugar, one egg and vanilla.','Pour the brownie base, dollop the cheesecake and the reserved batter over it.','Drag a knife through twice only — over-swirling muddies both.','Bake at 350°F for 35 minutes.'], 'Snack', 21504),
  ('c989fcb1-2ecd-5809-846b-7ce21d205e31'::uuid, 'Rice Pudding', array['1 cup arborio rice','6 cups whole milk','1/2 cup granulated sugar','1 tsp vanilla extract','1 cinnamon stick','1/4 cup raisins','Pinch of salt','Ground cinnamon to finish'], array['Simmer the rice in the milk with the cinnamon stick on the lowest heat, stirring often, 45 minutes.','Add sugar, vanilla, raisins and salt near the end.','It thickens a lot as it cools, so stop while it still looks loose.'], 'Snack', 22528)
) as r(id, title, ing, steps, meal, pos)
on conflict (id) do update set title = excluded.title, ingredients = excluded.ingredients, steps = excluded.steps, meal = excluded.meal;
